entries[41307] = { ["name"] = "Gyrobalancierter Khoriumzerstörer", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr , Khoriumbarren (20), Teufelsstahlstabilisator (4), Urfeuer (12), Urluft (12), Urnether\nGyrobalancierter Khoriumzerstörer\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n148 - 275 Schaden Tempo 2.80\n(75.54 Schaden pro Sekunde)\n+27 Ausdauer\n\nGelber Sockel\nSockelbonus: +3 Ausdauer\n\nHaltbarkeit 90 / 90\n70" }
