entries[41478] = { ["name"] = "Magie dämpfen", ["text"] = "600 Mana 30 Meter Reichweite\nSofort\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 75 und Heilzauber um bis zu 500 verringert werden. Hält 5 Min. lang an." }
