entries[41481] = { ["name"] = "Flammenstoß", ["text"] = "260 Mana Unbegrenzte Reichweite\nWirken in 1.5 sek. 3 sek. Abklingzeit\nLässt eine Flammensäule niedergehen, die alle Feinde im ausgewählten Gebiet verbrennt und ihnen 12 Sek. lang alle 2 Sek. zusätzlichen Schaden zufügt." }
entries[41482] = { ["name"] = "Blizzard", ["text"] = "100 Mana Unbegrenzte Reichweite\nSofort 3 sek. Abklingzeit\nRuft einen Blizzard herbei, der 12 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 4375 bis 5625 Frostschaden zufügt." }
