entries[41604] = { ["name"] = "Oberste Macht von Shattrath", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Schadenswirkung von Zaubern und magischen Effekten 2 Stunden lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
