entries[41607] = { ["name"] = "Stärkung von Shattrath", ["text"] = "Sofort\nErhöht die maximale Gesundheit des Spielers 2 Stunden lang um 500 und die Verteidigungswertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an." }
entries[41608] = { ["name"] = "Unerbitterlicher Angriff von Shattrath", ["text"] = "Sofort\nErhöht die Angriffskraft 2 Stunden lang um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau." }
