entries[41635] = { ["name"] = "Gebet der Besserung", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt das Ziel mit einem Zauber, der es um 800 heilt, wenn es das nächste Mal Schaden erleidet. Nachdem die Heilung ausgelöst wurde, springt 'Gebet der Besserung' zu einem Mitglied Eurer Schlachtgruppe innerhalb von 0 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig platziert werden." }
